-- DEC-046: preserve integer-only checks for binary JSON signed/unsigned storage.
-- Known local empty tables only; no row/state rewrite. Refuse already-applied/unknown target.
SET NAMES utf8mb4;
SET SESSION lock_wait_timeout=10;
CREATE TEMPORARY TABLE seckill_json_integer_guard(ok TINYINT NOT NULL CHECK(ok=1));
INSERT INTO seckill_json_integer_guard SELECT IF(@@hostname='QIANG' AND VERSION() LIKE '8.0.%' AND DATABASE()='qinghe_trade' AND (SELECT COUNT(*) FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_NAME IN('ck_trade_sc_outbox_payload') AND CHECK_CLAUSE NOT LIKE '%UNSIGNED INTEGER%')=1 AND (SELECT COUNT(*) FROM `trade_seckill_outbox`)=0,1,0);
ALTER TABLE `trade_seckill_outbox` DROP CHECK `ck_trade_sc_outbox_payload`, ADD CONSTRAINT `ck_trade_sc_outbox_payload` CHECK(((json_type(`payload`) = _utf8mb4'OBJECT') and (json_length(`payload`) = 4) and json_contains_path(`payload`,_utf8mb4'all',_utf8mb4'$.schemaVersion',_utf8mb4'$.tenantId',_utf8mb4'$.requestNo',_utf8mb4'$.aggregateVersion') and (json_type(json_extract(`payload`,_utf8mb4'$.schemaVersion')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`payload`,_utf8mb4'$.schemaVersion') = 1) and (json_type(json_extract(`payload`,_utf8mb4'$.tenantId')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`payload`,_utf8mb4'$.tenantId') = `tenant_id`) and (json_type(json_extract(`payload`,_utf8mb4'$.requestNo')) = _utf8mb4'STRING') and (json_unquote(json_extract(`payload`,_utf8mb4'$.requestNo')) = `request_no`) and (json_type(json_extract(`payload`,_utf8mb4'$.aggregateVersion')) IN ('INTEGER','UNSIGNED INTEGER')) and (json_extract(`payload`,_utf8mb4'$.aggregateVersion') = `aggregate_version`)));
SELECT 'SECKILL_JSON_INTEGER_COMPATIBILITY_READY' AS result;
